import json
import uuid

import splunk.pdf.pdfgen_utils as pdfgen_utils
import splunk.rest as rest

from splunk.pdf.pdfgen_search import BaseSearchManager

CHART_DATA_URI = "/o11y-chart-data"
DEFAULT_ERROR = "Unable to load observability data"

logger = pdfgen_utils.getLogger()

class O11yDataManager(BaseSearchManager):
    def __init__(self, ds_def, owner, sessionKey):
        BaseSearchManager.__init__(self, None, owner, sessionKey)
        self.ds_def = ds_def

        options = ds_def["options"]
        query_params = options.pop("queryParameters", {})

        # Use earliest and latest from query parameters if not already present in options.
        options.setdefault("earliest", query_params.get("earliest"))
        options.setdefault("latest", query_params.get("latest"))

    def dispatch_internal(self, **kwargs):
        logger.debug(f"Fetching O11y chart data: {self.ds_def}")

        try:
            serverResponse, raw_server_content = rest.simpleRequest(
                CHART_DATA_URI, jsonargs=json.dumps(self.ds_def), sessionKey=self.sessionKey, rawResult=True)
            server_content = json.loads(raw_server_content) if raw_server_content else None
        except Exception as e:
            logger.error("An error occurred when fetching chart data - %s - %s", self.ds_def, e)
            raise Exception(DEFAULT_ERROR) from e

        if serverResponse.status == 200 and server_content:
            logger.debug("Successfully fetched O11y chart data")
            return O11yJob(O11yChartData(server_content))
        elif serverResponse.status == 404:
            logger.error("Unable to reach %s, o11y app may not be installed correctly", CHART_DATA_URI)
            raise Exception(f"{DEFAULT_ERROR} - check configuration")
        elif server_content and "error" in server_content:
            logger.error("Error when retrieving O11y chart data - %s - %s", serverResponse.status, server_content)
            raise Exception(f"{DEFAULT_ERROR} - {server_content['error']}")
        else:
            raise Exception(DEFAULT_ERROR)


class O11yJob:
    def __init__(self, results):
        self.sid = str(uuid.uuid4())
        self.id = self.sid
        self.results = results
        self.resultCount = len(results.results)

    def isExpired(self):
        return False

    def isDone(self):
        return True

    def cancel(self):
        pass

    def __eq__(self, other):
        if not isinstance(other, O11yJob):
            return False
        return (
                self.sid == other.sid and
                self.id == other.id and
                self.results == other.results
        )

class O11yChartData:
    def __init__(self, results):
        self.results = results["data"]
        self.fieldOrderWithMeta = results["metadata"]

    def __iter__(self):
        return iter(self.results)

    def __eq__(self, other):
        if not isinstance(other, O11yChartData):
            return False
        return (
                self.results == other.results and
                self.fieldOrderWithMeta == other.fieldOrderWithMeta
        )